/**
 * The clause is applied to the damage first; the deductible comes off the result.
 *
 * This is one damage entry's contribution to the claim, not a payout in its own
 * right: it is pre-cap, unrounded, and goes negative when the damage is smaller
 * than the deductible. No test pins what should happen then — today such an entry
 * subtracts from its siblings, and a lone one yields a negative payout that raises
 * the remaining cap. Settle that rule before treating this value as a payout.
 */
const deductedReimbursementFor = (damage: Damage, policy: Policy): number => {
  const reimbursed = damage.amount * reimbursementRateFor(insuredItemFor(damage, policy));
  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
};

